/**
 * The global data manifest generated by the Vite plugin (scripts/dataManifest.mjs).
 * Its `version` is a hash of every runtime data file, so a "Recharger" click can
 * skip the whole download and rebuild when nothing changed.
 */
export interface DataManifest {
  generatedAt: string;
  version: string;
  files: Record<string, string>;
}

const manifestUrl = () => `${import.meta.env.BASE_URL}data/manifest.json`;

/** Adds the data version to a runtime URL, so a new deployment never mixes cached files. */
export function versionedUrl(url: string, version: string | null | undefined): string {
  if (!version) return url;
  return `${url}${url.includes("?") ? "&" : "?"}v=${encodeURIComponent(version)}`;
}

export async function fetchDataManifest(fetchImpl: typeof fetch = fetch): Promise<DataManifest | null> {
  try {
    const response = await fetchImpl(manifestUrl(), { cache: "no-cache" });
    if (!response.ok) return null;
    const data = (await response.json()) as Partial<DataManifest> | null;
    if (!data || typeof data.version !== "string" || typeof data.files !== "object" || data.files === null) return null;
    return data as DataManifest;
  } catch {
    return null;
  }
}
